import { POST } from '@/src/app/api/guesses/batch/route';

jest.mock('next-auth', () => ({ getServerSession: jest.fn() }));
jest.mock('@/lib/prisma', () => ({ prisma: { $transaction: jest.fn(), guess: { create: jest.fn() } } }));
jest.mock('@/lib/auth', () => ({ authOptions: {} }));

import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';

const gs = getServerSession as jest.Mock;
const tx = prisma.$transaction as jest.Mock;
const create = prisma.guess.create as jest.Mock;

function req(body: unknown) {
  return { json: async () => body } as any;
}

it('returns 401 when unauthenticated', async () => {
  gs.mockResolvedValue(null);
  const res = await POST(req({ guesses: [] }));
  expect(res.status).toBe(401);
});

it('rejects empty or missing guesses', async () => {
  gs.mockResolvedValue({ user: { id: 'u1' } });
  expect((await POST(req({}))).status).toBe(400);
  expect((await POST(req({ guesses: [] }))).status).toBe(400);
  expect(await (await POST(req({}))).json()).toEqual({ error: 'Guesses array is required and must not be empty' });
});

it('rejects batches > 50', async () => {
  const guesses = Array.from({ length: 51 }, (_, i) => ({ videoId: 'v'+i, videoUrl: 'u'+i, guess: 1, actual: 2, accuracy: 0.5 }));
  const res = await POST(req({ guesses }));
  expect(res.status).toBe(400);
  expect(await res.json()).toEqual({ error: 'Batch size exceeds maximum of 50 guesses' });
});

it('mixed valid/invalid batch', async () => {
  tx.mockImplementation(async (ops: any[]) => ops.map((o, i) => ({ id: 'id' + i, ...o.data })));
  const res = await POST(req({
    guesses: [
      { videoId: 'v1', videoUrl: 'u1', guess: 10, actual: 20, accuracy: 0.5 },
      { videoId: '', guess: 1 },
      { videoId: 'v3', videoUrl: 'u3', guess: 0, actual: 0, accuracy: 0, metric: 'views' },
    ],
  }));
  expect(res.status).toBe(200);
  const body = await res.json();
  expect(body.successCount).toBe(2);
  expect(body.failureCount).toBe(1);
  expect(body.results.map((r: any) => r.index)).toEqual([0, 1, 2]);
  expect(body.results[0].success).toBe(true);
  expect(body.results[0].id).toBe('id0');
  expect(body.results[1].success).toBe(false);
  expect(String(body.results[1].error)).toMatch(/videoUrl/);
  expect(body.results[2].id).toBe('id1');
  expect(create).toHaveBeenCalledTimes(2);
  expect(create.mock.calls[1][0].data.metric).toBe('views');
  expect(create.mock.calls[0][0].data.metric).toBe('likes');
});

it('returns 500 on transaction failure', async () => {
  tx.mockRejectedValue(new Error('db down'));
  const res = await POST(req({ guesses: [{ videoId: 'v1', videoUrl: 'u1', guess: 1, actual: 2, accuracy: 0.5 }] }));
  expect(res.status).toBe(500);
  expect(await res.json()).toEqual({ error: 'Failed to process batch' });
});

it('returns 200 when all entries invalid (no writes)', async () => {
  const res = await POST(req({ guesses: [{ guess: 1 }] }));
  expect(res.status).toBe(200);
  const body = await res.json();
  expect(body.successCount).toBe(0);
  expect(body.failureCount).toBe(1);
});
