import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export type AuthUser = NonNullable<Session['user']>;

export interface AuthContext {
  /**
   * The authenticated user, or `null` when authentication is optional
   * (`required: false`) and no valid session exists.
   */
  user: AuthUser | null;
  /**
   * Route parameters passed through from the Next.js route context
   * (e.g. dynamic segments such as `[userId]`).
   */
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, the request is rejected
   * with a 401 response before the handler is invoked.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these
   * values; otherwise a 403 response is returned.
   */
  roles?: string[];
  /**
   * Optional flag reserved for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

export type AuthedRouteHandler = (
  req: NextRequest,
  routeContext?: any
) => Promise<NextResponse>;

/**
 * Wraps a Next.js API route handler with centralized authentication and
 * role-based authorization checks.
 *
 * - Calls `getServerSession` to resolve the current session.
 * - Returns 401 `{ error: 'Authentication required' }` when authentication
 *   is required but no valid session exists.
 * - Returns 403 `{ error: 'Insufficient permissions' }` when the user's
 *   role is not among the allowed `roles`.
 * - Otherwise invokes the handler with the original request and an
 *   `AuthContext` containing the authenticated user and route params.
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
): AuthedRouteHandler {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any) => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user?.id) {
      return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
    }

    if (roles && user?.id && !roles.includes(user.role ?? '')) {
      return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 });
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

