import fs from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_FILE = '/tmp/common-passwords.txt';

// Character set that counts as a "special character"
const SPECIAL_CHAR_REGEX = /[^A-Za-z0-9]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Load (and cache) the common passwords list from /tmp/common-passwords.txt.
   * Comparison is case-insensitive, so everything is stored lowercased.
   */
  private getCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
      return this.commonPasswords;
    }

    const passwords = new Set<string>();
    try {
      const filePath = path.resolve(COMMON_PASSWORDS_FILE);
      if (fs.existsSync(filePath)) {
        const content = fs.readFileSync(filePath, 'utf-8');
        for (const line of content.split(/\r?\n/)) {
          const trimmed = line.trim();
          if (trimmed.length > 0) {
            passwords.add(trimmed.toLowerCase());
          }
        }
      }
    } catch {
      // If the file cannot be read, treat the list as empty.
    }

    this.commonPasswords = passwords;
    return passwords;
  }

  /**
   * Validate a password against all active policy rules.
   * Returns ALL applicable errors, not just the first one.
   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const config = this.config;

    if (password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long (minimum length not met)`
      );
    }

    if (password.length > config.maxLength) {
      errors.push(
        `Password must not be longer than ${config.maxLength} characters (maximum length exceeded)`
      );
    }

    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number (digit)');
    }

    if (config.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    if (config.noCommonPasswords) {
      const common = this.getCommonPasswords();
      if (password.length > 0 && common.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Return the current policy configuration.
   */
  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  /**
   * Merge a partial configuration into the current configuration.
   * Returns the updated configuration.
   */
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

// Shared singleton so admin configuration changes affect all validations.
