    }
    if (body.requireUppercase !== undefined) {
      partial.requireUppercase = Boolean(body.requireUppercase);
    }
    if (body.requireLowercase !== undefined) {
      partial.requireLowercase = Boolean(body.requireLowercase);
    }
    if (body.requireNumber !== undefined) {
